WITH flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM web_events), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('MONTH', event_time) AS activity_month, session_no, SIZE(COLLECT_SET(page)) AS num_pages, ROUND(SUM(is_new_session) / NULLIF(COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END), 0), 2) AS is_new_session_per_add_to_cart, SUM(CASE WHEN page = '/checkout' THEN is_new_session ELSE 0 END) AS checkout_is_new_session, COUNT(*) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_rows, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('MONTH', event_time) ORDER BY ROUND(SUM(is_new_session) / NULLIF(COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END), 0), 2) DESC) AS is_new_session_per_add_to_cart_dense_rank FROM sessionized GROUP BY DATE_TRUNC('MONTH', event_time), session_no ORDER BY add_to_cart_rows
